// Fuente: Horarios-develop/src/**/*.cs · script: scripts/gen-clases.py
// 299 tipos · 572 relaciones

export type CapaId =
  | 'dominio'
  | 'contratos'
  | 'aplicacion'
  | 'scheduler'
  | 'infraestructura'
  | 'blazor';

export type TipoClase = 'clase' | 'record' | 'interfaz' | 'enum' | 'struct';
export type TipoRelacion = 'hereda' | 'implementa' | 'depende' | 'usa';

export interface Miembro {
  /** Nombre; en métodos incluye la firma abreviada. */
  n: string;
  /** Tipo devuelto o del campo. Vacío en los valores de un enum. */
  t: string;
  k: 'prop' | 'metodo' | 'valor';
  /** Miembro estático. */
  est: boolean;
}

export interface Clase {
  /** Nombre completo con namespace: identificador único. */
  id: string;
  nombre: string;
  ns: string;
  capa: CapaId;
  /** Módulo funcional dentro de la capa: Academia, Docentes, Aulas… */
  modulo: string;
  kind: TipoClase;
  abst: boolean;
  /** Ruta del archivo dentro de src/. */
  archivo: string;
  x: number;
  y: number;
  w: number;
  h: number;
  grado: number;
  miembros: Miembro[];
}

export interface Relacion {
  id: string;
  de: string;
  a: string;
  tipo: TipoRelacion;
  /** Miembros o bases que motivan la relación. */
  via: string[];
}

export interface Capa {
  id: CapaId;
  label: string;
  descripcion: string;
  color: string;
  clases: number;
  /** Caja envolvente del cluster en el lienzo. */
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Subregión dentro de una capa: los tipos de un mismo módulo funcional. */
export interface Modulo {
  id: string;
  capa: CapaId;
  label: string;
  clases: number;
  x: number;
  y: number;
  w: number;
  h: number;
}

